contrast_ratio <- function(fg, bg) {
  lum <- function(hex) {
    rgb <- col2rgb(hex) / 255
    rgb <- ifelse(rgb <= .04045, rgb / 12.92, ((rgb + .055) / 1.055)^2.4)
    sum(rgb * c(.2126, .7152, .0722))
  }
  vals <- sort(c(lum(fg), lum(bg)))
  (vals[2] + .05) / (vals[1] + .05)
}

# Closest colour to `fg` (mixing towards black or white) that reaches `target` against `bg`.
passing_colour <- function(fg, bg, target = 4.5) {
  if (contrast_ratio(fg, bg) >= target) return(toupper(fg))
  base <- col2rgb(fg)[, 1]
  for (step in seq(0.05, 1, by = 0.05)) {
    for (towards in list(c(0, 0, 0), c(255, 255, 255))) {
      mixed <- rgb(t(round(base + (towards - base) * step)), maxColorValue = 255)
      if (contrast_ratio(mixed, bg) >= target) return(mixed)
    }
  }
  "#000000"
}

valid_hex <- function(x) grepl("^#[0-9A-Fa-f]{6}$", x %||% "")

colour_presets <- setNames(list(c("#9A9A9A", "#FFFFFF"), c("#FFFFFF", "#3FA34D"), c("#1D2B53", "#F2E3C6"), c("#D0312D", "#111111")),
  c(tr("Grey on white", "Gris sobre blanco"), tr("White on green", "Blanco sobre verde"), tr("Navy on sand", "Azul marino sobre arena"), tr("Red on black", "Rojo sobre negro")))

barrier_items <- list(
  list(id = "img", answer = "alt",
       example = tr("A product photo is announced by a screen reader as \"IMG_2041.jpg\".", "Un lector de pantalla anuncia la foto de un producto como «IMG_2041.jpg»."),
       why = tr("Images that carry meaning need a text alternative (WCAG 1.1.1).", "Las imágenes con significado necesitan una alternativa textual (WCAG 1.1.1).")),
  list(id = "field", answer = "label",
       example = tr("A form field shows the hint \"Email\" inside the box, which disappears as soon as you type.", "Un campo muestra la pista «Correo» dentro de la caja, que desaparece en cuanto escribes."),
       why = tr("Placeholders are not labels: once they vanish, people must remember what the field was (WCAG 3.3.2).", "Un texto de ejemplo no es una etiqueta: cuando desaparece, hay que recordar qué pedía el campo (WCAG 3.3.2).")),
  list(id = "colour", answer = "colour",
       example = tr("Required fields that were left empty are shown only with a red border.", "Los campos obligatorios que se dejaron vacíos solo se marcan con un borde rojo."),
       why = tr("Colour alone does not reach everyone; add text or an icon (WCAG 1.4.1).", "El color por sí solo no llega a todo el mundo; añade texto o un icono (WCAG 1.4.1).")),
  list(id = "focus", answer = "focus",
       example = tr("Pressing Tab moves through the page, but there is no visible sign of where you are.", "Al pulsar Tab te mueves por la página, pero no se ve dónde estás."),
       why = tr("Keyboard users need a visible focus indicator (WCAG 2.4.7).", "Quien usa el teclado necesita un indicador de foco visible (WCAG 2.4.7)."))
)
barrier_choices <- setNames(c("", "alt", "label", "colour", "focus"),
  c(tr("Choose the barrier", "Elige la barrera"), tr("Missing text alternative", "Falta alternativa textual"), tr("Missing visible label", "Falta etiqueta visible"),
    tr("Information conveyed by colour only", "Información transmitida solo con color"), tr("No visible keyboard focus", "Sin foco de teclado visible")))

accessibility_ui <- function(id) {
  ns <- NS(id)
  lab_section(ns,
    objectives = c(tr("Check text and background contrast.", "Comprobar el contraste entre texto y fondo."),
                   tr("Interpret a ratio using WCAG thresholds.", "Interpretar una ratio con los umbrales de las WCAG."),
                   tr("Recognise barriers that a contrast check cannot detect.", "Reconocer barreras que una comprobación de contraste no detecta.")),
    concept = tr("WCAG asks for a contrast ratio of at least 4.5:1 for normal text and 3:1 for large text. Passing contrast is necessary, but it is only one of many success criteria.",
                 "Las WCAG piden una ratio de contraste de al menos 4,5:1 para texto normal y 3:1 para texto grande. Superar el contraste es necesario, pero es solo uno de muchos criterios de conformidad."),
    activity = navset_underline(
      nav_panel(tr("Contrast checker", "Comprobador de contraste"),
        div(class = "pt-3",
          p(tr("Try a preset, or type two hex colours.", "Prueba una combinación predefinida o escribe dos colores hexadecimales.")),
          div(class = "d-flex flex-wrap gap-2 mb-3", lapply(names(colour_presets), function(name)
            tags$button(class = "btn btn-sm btn-outline-secondary", type = "button", name,
                        onclick = js_event(ns("preset"), sprintf("'%s'", name))))),
          layout_columns(col_widths = c(6, 6),
            div(textInput(ns("fg"), tr("Text colour (hex)", "Color del texto (hex)"), "#202522"),
                textInput(ns("bg"), tr("Background colour (hex)", "Color de fondo (hex)"), "#FFFFFF"),
                sliderInput(ns("size"), tr("Text size (pt)", "Tamaño del texto (pt)"), min = 8, max = 36, value = 16)),
            div(uiOutput(ns("result")))),
          div(class = "mt-3 p-4 border rounded", uiOutput(ns("sample"))))),
      nav_panel(tr("Spot the barrier", "Detecta la barrera"),
        div(class = "pt-3",
          p(tr("Each example passes a contrast check. Name the barrier that remains.", "Todos los ejemplos superan la comprobación de contraste. Indica la barrera que queda.")),
          lapply(barrier_items, function(item) div(class = "panel-soft mb-2",
            p(class = "mb-2", item$example),
            selectInput(ns(paste0("barrier_", item$id)), NULL, barrier_choices, width = "100%"))),
          actionButton(ns("check"), tr("Check my answers", "Comprobar mis respuestas"), class = "btn-primary"),
          uiOutput(ns("barrier_feedback"))))),
    reflection = tr("What other barriers could remain even if the contrast ratio passes? How would you find them?",
                    "¿Qué otras barreras podrían quedar aunque el contraste sea suficiente? ¿Cómo las encontrarías?"))
}

accessibility_server <- function(id) {
  moduleServer(id, function(input, output, session) {
    observeEvent(input$preset, {
      pair <- colour_presets[[input$preset]]
      updateTextInput(session, "fg", value = pair[1]); updateTextInput(session, "bg", value = pair[2])
    })
    valid <- reactive(valid_hex(input$fg) && valid_hex(input$bg))
    ratio <- reactive({ req(valid()); contrast_ratio(input$fg, input$bg) })
    large <- reactive(input$size >= 18)
    fmt_ratio <- function(r) if (LANG == "es") paste0(formatC(r, format = "f", digits = 2, decimal.mark = ","), ":1") else sprintf("%.2f:1", r)

    output$result <- renderUI({
      if (!valid()) return(div(class = "alert alert-warning", tr("Enter colours as six-digit hex values, e.g. #202522.", "Escribe los colores como valores hexadecimales de seis dígitos, p. ej. #202522.")))
      r <- ratio()
      target <- if (large()) 3 else 4.5
      level <- if (r >= 7) tr("Passes AAA for normal text", "Cumple AAA para texto normal")
               else if (r >= 4.5) tr("Passes AA for normal text", "Cumple AA para texto normal")
               else if (r >= 3) tr("Passes AA for large text only", "Cumple AA solo para texto grande")
               else tr("Below WCAG AA thresholds", "Por debajo de los umbrales AA de las WCAG")
      suggestion <- if (r < target) {
        fix <- passing_colour(input$fg, input$bg, target)
        p(class = "mb-0 mt-2", tr("Closest passing text colour: ", "Color de texto válido más cercano: "), tags$code(fix), " ",
          tags$a(href = "#", onclick = js_event(session$ns("apply_fix"), sprintf("'%s'", fix)), tr("Use it", "Usarlo")))
      }
      div(class = if (r >= target) "alert alert-success" else "alert alert-warning", role = "status",
        tags$strong(style = "font-size:1.6rem", fmt_ratio(r)), br(), level,
        br(), span(class = "footnote", if (large()) tr("At this size the text counts as large (3:1 needed).", "A este tamaño el texto cuenta como grande (se necesita 3:1).")
                                       else tr("Normal text needs 4.5:1.", "El texto normal necesita 4,5:1.")),
        suggestion)
    })
    observeEvent(input$apply_fix, updateTextInput(session, "fg", value = input$apply_fix))

    output$sample <- renderUI({
      if (!valid()) return(tr("The preview appears when both colours are valid.", "La vista previa aparece cuando los dos colores son válidos."))
      div(style = sprintf("color:%s;background:%s;font-size:%spt;padding:1rem;border-radius:.4rem", input$fg, input$bg, input$size),
          tr("Readable interface text should remain legible across screens, lighting, and eyesight.", "El texto de una interfaz debe seguir siendo legible con distintas pantallas, luz y capacidades visuales."))
    })

    checked <- reactiveVal(FALSE)
    observeEvent(input$check, checked(TRUE))
    output$barrier_feedback <- renderUI({
      req(checked())
      answers <- vapply(barrier_items, function(item) input[[paste0("barrier_", item$id)]] %||% "", "")
      right <- answers == vapply(barrier_items, `[[`, "", "answer")
      div(class = "mt-3",
        div(class = if (all(right)) "alert alert-success" else "alert alert-info", sprintf(tr("%d of %d identified.", "%d de %d identificadas."), sum(right), length(right))),
        tags$ul(class = "check-list", lapply(seq_along(barrier_items), function(i) tags$li(class = if (right[i]) "ok" else "todo", barrier_items[[i]]$why))))
    })

    observeEvent(input$example, {
      pair <- colour_presets[[1]]
      updateTextInput(session, "fg", value = pair[1]); updateTextInput(session, "bg", value = pair[2])
      for (item in barrier_items) updateSelectInput(session, paste0("barrier_", item$id), selected = item$answer)
      updateSelectInput(session, "barrier_focus", selected = "colour")
      checked(TRUE)
      example_reflection(session, tr(
        "Grey on white fails for normal text, and the suggested darker grey passes. Contrast alone would miss the missing labels and the invisible keyboard focus: I would also test with a keyboard and a screen reader.",
        "El gris sobre blanco no llega para texto normal, y el gris más oscuro sugerido sí. El contraste por sí solo no detectaría las etiquetas que faltan ni el foco invisible: probaría también con teclado y lector de pantalla."))
    })

    reflect_server(tr("Accessibility", "Accesibilidad"), input, output, session, function() {
      if (!valid()) return(tr("(no valid colour pair)", "(sin pareja de colores válida)"))
      sprintf(tr("Text %s on %s at %spt: contrast %s", "Texto %s sobre %s a %s pt: contraste %s"), toupper(input$fg), toupper(input$bg), input$size, fmt_ratio(ratio()))
    })
  })
}

// IxD Lab · optional AI feedback and tutor with the visitor's own API key: Claude (Anthropic),
// ChatGPT (OpenAI) or Gemini (Google). The key and the request stay in the browser: they go
// straight to the provider, never to the Shiny server, and the key input has no id so Shiny
// never binds it.
(function () {
  const PROVIDER_STORE = "ixd-lab-ai-provider";
  const keyStore = (p) => "ixd-lab-key-" + p;

  const PROVIDERS = {
    claude: {
      label: "Claude",
      model: "claude-opus-5-5",
      valid: (k) => k.startsWith("sk-ant-"),
      async ask(key, model, system, messages) {
        const res = await fetch("https://api.anthropic.com/v1/messages", {
          method: "POST",
          headers: {
            "content-type": "application/json",
            "x-api-key": key,
            "anthropic-version": "2026-10-21",
            "anthropic-beta": "server-side-fallback-2026-07-01",
            "anthropic-dangerous-direct-browser-access": "true"
          },
          body: JSON.stringify({
            model: model,
            max_tokens: 16000,
            fallbacks: "default",
            output_config: { effort: "medium" },
            system: system,
            messages: messages
          })
        });
        const data = await res.json().catch(() => ({}));
        if (!res.ok) return { status: res.status, detail: data.error && data.error.message };
        if (data.stop_reason === "refusal") return { refusal: true };
        return { text: (data.content || []).filter((b) => b.type === "text").map((b) => b.text).join("\n") };
      }
    },
    openai: {
      label: "ChatGPT",
      model: "gpt-5",
      valid: (k) => k.startsWith("sk-"),
      async ask(key, model, system, messages) {
        const res = await fetch("https://api.openai.com/v1/chat/completions", {
          method: "POST",
          headers: { "content-type": "application/json", "authorization": "Bearer " + key },
          body: JSON.stringify({ model: model, messages: [{ role: "system", content: system }].concat(messages) })
        });
        const data = await res.json().catch(() => ({}));
        if (!res.ok) return { status: res.status, detail: data.error && data.error.message };
        const choice = (data.choices || [])[0] || {};
        if (choice.message && choice.message.refusal) return { refusal: true };
        return { text: (choice.message && choice.message.content) || "" };
      }
    },
    gemini: {
      label: "Gemini",
      model: "gemini-flash-latest",
      valid: (k) => k.startsWith("AIza"),
      async ask(key, model, system, messages) {
        const url = "https://generativelanguage.googleapis.com/v1beta/models/" + encodeURIComponent(model) + ":generateContent";
        const res = await fetch(url, {
          method: "POST",
          headers: { "content-type": "application/json", "x-goog-api-key": key },
          body: JSON.stringify({
            systemInstruction: { parts: [{ text: system }] },
            contents: messages.map((m) => ({ role: m.role === "assistant" ? "model" : "user", parts: [{ text: m.content }] }))
          })
        });
        const data = await res.json().catch(() => ({}));
        if (!res.ok) {
          // Gemini reports a bad key as 400 INVALID_ARGUMENT with reason API_KEY_INVALID.
          const msg = data.error && data.error.message;
          return { status: /api key/i.test(msg || "") ? 401 : res.status, detail: msg };
        }
        const cand = (data.candidates || [])[0];
        if (!cand) return data.promptFeedback && data.promptFeedback.blockReason ? { refusal: true } : { text: "" };
        if (cand.finishReason === "SAFETY") return { refusal: true };
        return { text: ((cand.content && cand.content.parts) || []).map((p) => p.text || "").join("") };
      }
    }
  };

  function read(store) {
    try { return sessionStorage.getItem(store) || localStorage.getItem(store) || ""; } catch (e) { return ""; }
  }
  function write(store, value, remember) {
    try {
      sessionStorage.removeItem(store);
      localStorage.removeItem(store);
      if (value) (remember ? localStorage : sessionStorage).setItem(store, value);
    } catch (e) { /* storage blocked: the value is simply not kept */ }
  }

  // Keys saved by IxD Lab 0.1 (Claude only) keep working.
  (function migrate() {
    try {
      const old = localStorage.getItem("ixd-lab-anthropic-key") || sessionStorage.getItem("ixd-lab-anthropic-key");
      if (old && !read(keyStore("claude"))) write(keyStore("claude"), old, Boolean(localStorage.getItem("ixd-lab-anthropic-key")));
      localStorage.removeItem("ixd-lab-anthropic-key");
      sessionStorage.removeItem("ixd-lab-anthropic-key");
    } catch (e) {}
  })();

  function provider() {
    const p = read(PROVIDER_STORE);
    return PROVIDERS[p] ? p : "claude";
  }
  function getKey(p) { return read(keyStore(p || provider())); }
  function getModel(p) { return read("ixd-lab-model-" + (p || provider())) || PROVIDERS[p || provider()].model; }

  function el(sel) { return document.querySelector(sel); }

  function refreshStatus() {
    const p = provider();
    const on = Boolean(getKey(p));
    document.body.classList.toggle("ai-on", on);
    document.querySelectorAll("[data-ixd-ai-provider-name]").forEach((n) => { n.textContent = PROVIDERS[p].label; });
    try { Shiny.setInputValue("ai_provider", on ? PROVIDERS[p].label : ""); } catch (e) { /* Shiny not connected yet */ }
  }

  // Shows the chosen provider's key hint, link and saved state in the settings dialog.
  function showProvider(p) {
    document.querySelectorAll("[data-ixd-ai-pick]").forEach((r) => { r.checked = r.value === p; });
    document.querySelectorAll("[data-ixd-ai-for]").forEach((n) => { n.hidden = n.dataset.ixdAiFor !== p; });
    const input = el("[data-ixd-ai-key]");
    input.value = "";
    input.placeholder = getKey(p) ? "••••••••  (" + input.dataset.saved + ")" : input.dataset["ph" + p];
    el("[data-ixd-ai-model]").value = read("ixd-lab-model-" + p);
    el("[data-ixd-ai-model]").placeholder = PROVIDERS[p].model;
    el("[data-ixd-ai-message]").textContent = "";
  }

  function modal() {
    return bootstrap.Modal.getOrCreateInstance(document.getElementById("ai-settings"));
  }

  function chosen() {
    const r = el("[data-ixd-ai-pick]:checked");
    return r ? r.value : provider();
  }

  function save() {
    const p = chosen();
    const input = el("[data-ixd-ai-key]");
    const message = el("[data-ixd-ai-message]");
    const remember = el("[data-ixd-ai-remember]").checked;
    const key = input.value.trim();
    if (!key && !getKey(p)) {
      message.textContent = message.dataset.missing;
      input.focus();
      return;
    }
    if (key && !PROVIDERS[p].valid(key)) {
      message.textContent = message.dataset["invalid" + p];
      input.focus();
      return;
    }
    if (key) write(keyStore(p), key, remember);
    write("ixd-lab-model-" + p, el("[data-ixd-ai-model]").value.trim(), remember);
    write(PROVIDER_STORE, p, true);
    input.value = "";
    refreshStatus();
    modal().hide();
  }

  function clear() {
    const p = chosen();
    write(keyStore(p), "", false);
    write("ixd-lab-model-" + p, "", false);
    showProvider(p);
    refreshStatus();
  }

  function reply(target, value) {
    Shiny.setInputValue(target, Object.assign({ nonce: Date.now() }, value), { priority: "event" });
  }

  async function ask(msg) {
    const p = provider();
    const key = getKey(p);
    if (!key) {
      reply(msg.target, { error: "nokey" });
      modal().show();
      return;
    }
    try {
      const r = await PROVIDERS[p].ask(key, getModel(p), msg.system, msg.messages);
      const label = PROVIDERS[p].label;
      if (r.refusal) return reply(msg.target, { error: "refusal", provider: label });
      if (r.status) {
        const code = r.status === 401 || r.status === 403 ? "auth" : r.status === 429 || r.status === 529 ? "rate" : "api";
        return reply(msg.target, { error: code, provider: label, detail: r.detail || String(r.status) });
      }
      const text = (r.text || "").trim();
      reply(msg.target, text ? { text: text, provider: label } : { error: "api", provider: label, detail: "empty response" });
    } catch (e) {
      reply(msg.target, { error: "network", detail: String(e) });
    }
  }

  window.ixdAI = { save: save, clear: clear, pick: showProvider };
  document.addEventListener("DOMContentLoaded", function () {
    refreshStatus();
    const dialog = document.getElementById("ai-settings");
    if (dialog) dialog.addEventListener("show.bs.modal", () => showProvider(provider()));
  });
  $(document).on("shiny:connected", function () {
    Shiny.addCustomMessageHandler("ixd-ai-request", ask);
    refreshStatus();
  });
})();

// IxD Lab · browser-side helpers: notes saved in this browser, and the timed experiments of the
// Laws of UX lab (Fitts's and Hick's laws), which need millisecond timing in the page.
(function () {
  const lang = () => document.documentElement.lang || "en";
  const noteKey = (id) => "ixd-notes-" + lang() + "-" + id;

  // ---- Notes: every "…-reflection" textarea is kept in localStorage, on this device only.
  function restoreNotes() {
    document.querySelectorAll("textarea[id$='-reflection']").forEach((el) => {
      let saved = "";
      try { saved = localStorage.getItem(noteKey(el.id)) || ""; } catch (e) {}
      if (saved && !el.value) $(el).val(saved).trigger("change");
    });
  }
  $(document).on("input change", "textarea[id$='-reflection']", function () {
    try {
      if (this.value) localStorage.setItem(noteKey(this.id), this.value);
      else localStorage.removeItem(noteKey(this.id));
    } catch (e) {}
  });
  window.ixdClearNotes = function () {
    try {
      Object.keys(localStorage).filter((k) => k.startsWith("ixd-notes-")).forEach((k) => localStorage.removeItem(k));
    } catch (e) {}
    document.querySelectorAll("textarea[id$='-reflection']").forEach((el) => $(el).val("").trigger("change"));
  };
  $(document).on("shiny:sessioninitialized", () => setTimeout(restoreNotes, 300));

  // ---- Fitts's law: click targets of different sizes and distances as fast as you can.
  const FITTS_TRIALS = 18;
  function fittsStart(area) {
    const input = area.dataset.fitts;
    const box = area.querySelector(".exp-stage");
    const status = area.querySelector(".exp-status");
    const sizes = [20, 40, 80];
    const data = { d: [], w: [], t: [], misses: 0 };
    let last = { x: box.clientWidth / 2, y: box.clientHeight / 2 };
    let shownAt = 0;
    let n = 0;
    box.innerHTML = "";
    box.onclick = (e) => { if (e.target === box) data.misses++; };
    function next() {
      if (n >= FITTS_TRIALS) {
        box.innerHTML = "<p class='exp-done'>" + area.dataset.done + "</p>";
        box.onclick = null;
        Shiny.setInputValue(input, Object.assign({ nonce: Date.now() }, data), { priority: "event" });
        return;
      }
      const w = sizes[Math.floor(Math.random() * sizes.length)];
      let x, y, d;
      do {
        x = w / 2 + Math.random() * (box.clientWidth - w);
        y = w / 2 + Math.random() * (box.clientHeight - w);
        d = Math.hypot(x - last.x, y - last.y);
      } while (d < 60);
      const t = document.createElement("button");
      t.type = "button";
      t.className = "fitts-target";
      t.setAttribute("aria-label", area.dataset.target);
      Object.assign(t.style, { width: w + "px", height: w + "px", left: (x - w / 2) + "px", top: (y - w / 2) + "px" });
      t.onclick = (e) => {
        e.stopPropagation();
        data.d.push(Math.round(d)); data.w.push(w); data.t.push(Math.round(performance.now() - shownAt));
        last = { x: x, y: y };
        t.remove();
        n++;
        status.textContent = n + " / " + FITTS_TRIALS;
        next();
      };
      box.appendChild(t);
      shownAt = performance.now();
    }
    status.textContent = "0 / " + FITTS_TRIALS;
    next();
  }

  // ---- Hick's law: find a word among 2, 4, 8 or 16 choices.
  const HICK_WORDS = {
    en: ["Madrid", "Lisbon", "Paris", "Berlin", "Rome", "Vienna", "Prague", "Dublin", "Oslo", "Athens", "Warsaw", "Brussels", "Helsinki", "Sofia", "Riga", "Bern"],
    es: ["Madrid", "Lisboa", "París", "Berlín", "Roma", "Viena", "Praga", "Dublín", "Oslo", "Atenas", "Varsovia", "Bruselas", "Helsinki", "Sofía", "Riga", "Berna"]
  };
  function shuffle(a) { for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; } return a; }
  function hickStart(area) {
    const input = area.dataset.hick;
    const box = area.querySelector(".exp-stage");
    const status = area.querySelector(".exp-status");
    const words = HICK_WORDS[lang()] || HICK_WORDS.en;
    const plan = shuffle([2, 4, 8, 16, 2, 4, 8, 16, 2, 4, 8, 16, 2, 4, 8, 16]);
    const data = { n: [], t: [], errors: 0 };
    let i = 0;
    function next() {
      if (i >= plan.length) {
        box.innerHTML = "<p class='exp-done'>" + area.dataset.done + "</p>";
        Shiny.setInputValue(input, Object.assign({ nonce: Date.now() }, data), { priority: "event" });
        return;
      }
      const options = shuffle(words.slice()).slice(0, plan[i]);
      const goal = options[Math.floor(Math.random() * options.length)];
      box.innerHTML = "<p class='hick-goal'>" + area.dataset.find + " <strong>" + goal + "</strong></p><div class='hick-grid'></div>";
      const grid = box.querySelector(".hick-grid");
      const shownAt = performance.now();
      options.forEach((w) => {
        const b = document.createElement("button");
        b.type = "button";
        b.className = "btn btn-outline-secondary btn-sm";
        b.textContent = w;
        b.onclick = () => {
          if (w !== goal) { data.errors++; b.classList.add("hick-wrong"); return; }
          data.n.push(plan[i]); data.t.push(Math.round(performance.now() - shownAt));
          i++;
          status.textContent = i + " / " + plan.length;
          next();
        };
        grid.appendChild(b);
      });
    }
    status.textContent = "0 / " + plan.length;
    next();
  }

  $(document).on("click", "[data-exp-start]", function () {
    const area = this.closest("[data-fitts], [data-hick]");
    if (area.dataset.fitts) fittsStart(area); else hickStart(area);
  });
})();

/* IxD Lab · editorial studio styles */
:root {
  --ixd-ink: #202522;
  --ixd-muted: #5f665f;
  --ixd-paper: #f6f4ef;
  --ixd-card: #ffffff;
  --ixd-line: #e3e0d7;
  --ixd-green: #276b5b;
  --ixd-green-dark: #1f5649;
  --ixd-sand: #d4a15e;
  --ixd-wire: #eeece6;
  --ixd-mono: ui-monospace, "Cascadia Mono", Consolas, "SF Mono", Menlo, monospace;
  --ixd-serif: Georgia, "Times New Roman", serif;
}

body { font-family: system-ui, -apple-system, "Segoe UI", sans-serif; background: var(--ixd-paper); color: var(--ixd-ink); }
h1, h2, h3, h4 { font-family: var(--ixd-serif); font-weight: 400; }
h3 { font-size: 1.35rem; margin: .6rem 0 .8rem; }
a { color: var(--ixd-green); }
:focus-visible { outline: 3px solid var(--ixd-sand) !important; outline-offset: 2px; }

.skip-link { position: absolute; left: -999px; top: .5rem; z-index: 2000; background: var(--ixd-ink); color: #fff; padding: .5rem 1rem; border-radius: .4rem; }
.skip-link:focus { left: .5rem; }

/* Navigation */
.navbar { border-bottom: 1px solid var(--ixd-line); background: rgba(246, 244, 239, .94) !important; backdrop-filter: blur(6px); }
.brand-mark { font-family: var(--ixd-mono); color: var(--ixd-green); font-weight: 500; }
.nav-link { font-size: .92rem; }

/* Typography helpers */
.eyebrow, .lab-num { font: 500 .74rem var(--ixd-mono); letter-spacing: .1em; text-transform: uppercase; color: var(--ixd-muted); }
.muted { color: var(--ixd-muted); }
.footnote { font-size: .84rem; color: var(--ixd-muted); }
.btn-primary { --bs-btn-bg: var(--ixd-green); --bs-btn-border-color: var(--ixd-green); --bs-btn-hover-bg: var(--ixd-green-dark); --bs-btn-hover-border-color: var(--ixd-green-dark); --bs-btn-active-bg: var(--ixd-green-dark); }
.btn-outline-success { --bs-btn-color: var(--ixd-green); --bs-btn-border-color: var(--ixd-green); --bs-btn-hover-bg: var(--ixd-green); --bs-btn-hover-border-color: var(--ixd-green); }

/* Home */
.hero { padding: 4.5rem 0 3rem; max-width: 880px; }
.hero h1 { font: 400 clamp(2.6rem, 7vw, 5.4rem)/.98 var(--ixd-serif); letter-spacing: -.045em; margin: 1.2rem 0; }
.hero p.lead-text { font-size: 1.15rem; max-width: 640px; color: var(--ixd-muted); }
.hero-actions { display: flex; flex-wrap: wrap; align-items: center; gap: 1rem; margin-top: 1.5rem; }
.section-title { font: 400 2rem var(--ixd-serif); margin: 0 0 1.2rem; }
.steps { display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 1rem; margin-bottom: 3.5rem; }
.step { border-top: 2px solid var(--ixd-green); padding-top: 1rem; }
.step h3 { margin-top: .4rem; }
.lab-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(280px, 1fr)); gap: 1.2rem; margin-bottom: 3.5rem; }
.lab-card { display: flex; flex-direction: column; padding: 1.5rem; background: var(--ixd-card); border: 1px solid var(--ixd-line); border-radius: 1rem; color: inherit; text-decoration: none; transition: transform .2s, border-color .2s, box-shadow .2s; }
.lab-card:hover, .lab-card:focus-visible { transform: translateY(-3px); border-color: var(--ixd-green); box-shadow: 0 10px 24px rgba(32, 37, 34, .06); color: inherit; }
.lab-card h3 { font-size: 1.6rem; margin: .8rem 0 .4rem; }
.lab-card p { color: var(--ixd-muted); flex: 1; }
.lab-card .go { color: var(--ixd-green); font-weight: 500; }
.teacher-box { background: var(--ixd-card); border: 1px solid var(--ixd-line); border-radius: 1rem; padding: 2rem; margin-bottom: 3rem; }

/* Lab pages */
.lab-head { padding: 2.2rem 0 1.2rem; }
.lab-head h1 { font-size: clamp(2.2rem, 5vw, 3.2rem); margin: .4rem 0; }
.lab-pager { display: flex; justify-content: space-between; gap: 1rem; margin-top: 2rem; }
.lab-pager a { text-decoration: none; }
.experiment { background: var(--ixd-card); border: 1px solid var(--ixd-line); padding: 1.6rem; border-radius: 1rem; }
.concept { background: #f1f6f3; border-radius: .8rem; padding: 1rem 1.2rem; }
.panel-soft { background: var(--ixd-paper); border: 1px solid var(--ixd-line); border-radius: .8rem; padding: 1rem; }
.chip { display: inline-block; font: 500 .72rem var(--ixd-mono); text-transform: uppercase; letter-spacing: .05em; padding: .15rem .55rem; border-radius: 99px; background: #e5efe9; color: var(--ixd-green-dark); }
.chip-warn { background: #f7ead6; color: #7a5520; }
.check-list { list-style: none; padding: 0; margin: 0; }
.check-list li { padding: .35rem 0; border-bottom: 1px dashed var(--ixd-line); }
.check-list li:last-child { border-bottom: 0; }
.ok::before { content: "✓ "; color: var(--ixd-green); font-weight: 700; }
.todo::before { content: "○ "; color: #a0763a; font-weight: 700; }

/* Wireframing canvas */
.wire-canvas { min-height: 420px; background: var(--ixd-wire); border: 1px dashed #c9c6bd; padding: 1rem; border-radius: .6rem; margin: 0 auto; transition: max-width .3s; }
.wire-item { background: #fff; padding: .7rem .8rem; margin: .5rem 0; border: 1px solid #dedbd2; border-radius: .4rem; display: flex; align-items: center; gap: .8rem; }
.wire-item .wf { flex: 1; min-width: 0; }
.wire-tools { display: flex; gap: .25rem; }
.wire-tools .btn { padding: .1rem .45rem; font-size: .8rem; }
.wf-label { font: 500 .68rem var(--ixd-mono); color: var(--ixd-muted); text-transform: uppercase; display: block; margin-bottom: .3rem; }
.wf-bar { height: .7rem; background: #d9d6ce; border-radius: 3px; margin: .25rem 0; }
.wf-heading .wf-bar { height: 1.3rem; width: 70%; background: #bdb9ae; }
.wf-nav .wf-row, .wf-cards .wf-row { display: flex; gap: .4rem; }
.wf-nav .wf-bar { width: 18%; }
.wf-image { height: 90px; border: 1px solid #c9c6bd; border-radius: 3px; background: linear-gradient(to top right, transparent calc(50% - 1px), #c9c6bd, transparent calc(50% + 1px)), linear-gradient(to top left, transparent calc(50% - 1px), #c9c6bd, transparent calc(50% + 1px)); }
.wf-button { display: inline-block; width: 140px; height: 2rem; background: var(--ixd-green); opacity: .8; border-radius: 99px; }
.wf-field { height: 2rem; border: 1.5px solid #bdb9ae; border-radius: 4px; background: #fff; }
.wf-cards .wf-card { flex: 1; height: 60px; border: 1px solid #d9d6ce; border-radius: 4px; background: #f7f6f2; }
.wf-footer .wf-bar { background: #e6e3db; }

/* Usability mock-ups */
.mock { background: #fff; border: 1px solid #d4d1c8; border-radius: .6rem; padding: 1rem 1.2rem; max-width: 420px; }
.mock-bar { font: 500 .7rem var(--ixd-mono); color: var(--ixd-muted); border-bottom: 1px solid var(--ixd-line); padding-bottom: .4rem; margin-bottom: .8rem; }
.mock .form-control { pointer-events: none; }

/* Behaviour timeline */
.trace-row { display: grid; grid-template-columns: 9rem 1fr 3.5rem; align-items: center; gap: .6rem; margin: .35rem 0; font-size: .92rem; }
.trace-bar { height: 1.1rem; background: var(--ixd-green); opacity: .75; border-radius: 3px; }
.trace-bar.help { background: var(--ixd-sand); opacity: 1; }
.trace-bar.back { background: #a35b4f; }
.legend span { margin-right: 1rem; font-size: .82rem; }
.legend i { display: inline-block; width: .8rem; height: .8rem; border-radius: 2px; margin-right: .3rem; vertical-align: -1px; }

/* Footer */
.site-footer { border-top: 1px solid var(--ixd-line); margin-top: 3rem; padding: 2rem 0 3rem; }
.site-footer a { color: var(--ixd-muted); }

@media (max-width: 576px) {
  .hero { padding-top: 2.5rem; }
  .experiment { padding: 1.1rem; }
  .trace-row { grid-template-columns: 6.5rem 1fr 3rem; font-size: .85rem; }
}

/* Language switch */
.lang-switch { font: 500 .8rem var(--ixd-mono); letter-spacing: .08em; border: 1px solid var(--ixd-line); border-radius: 99px; padding: .2rem .7rem !important; margin: .4rem 0; }
.lang-switch:hover { border-color: var(--ixd-green); color: var(--ixd-green); }

/* Optional AI feedback */
.ai-switch { display: inline-flex; align-items: center; gap: .35rem; }
.ai-dot { width: .5rem; height: .5rem; border-radius: 50%; background: #bdb9ae; }
body.ai-on .ai-dot { background: var(--ixd-green); }
body.ai-on .ai-off-text, body:not(.ai-on) .ai-on-text { display: none; }
.ai-feedback { background: #f1f6f3; border-left: 3px solid var(--ixd-green); border-radius: .6rem; padding: 1rem 1.2rem; }
.ai-feedback li { margin-bottom: .35rem; }

/* Examples, progress and portfolio */
.example-link { font-weight: 500; }
.portfolio-row { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 1rem; border-top: 1px solid var(--ixd-line); margin-top: 1.2rem; padding-top: 1.2rem; }

/* IxD Lab 0.2 · modules, progress and AI box */
.module { margin-bottom: 2.5rem; }
.module-head { border-top: 2px solid var(--ixd-green); padding-top: 1rem; margin-bottom: 1.2rem; }
.progress-box, .ai-box { background: var(--ixd-card); border: 1px solid var(--ixd-line); border-radius: 1rem; padding: 1.4rem 1.6rem; margin-bottom: 3rem; }
.ai-box { background: #f1f6f3; border-color: #cfe1d8; }
.meter { position: relative; height: .7rem; background: var(--ixd-wire); border-radius: 99px; overflow: visible; }
.meter-fill { height: 100%; background: var(--ixd-green); border-radius: 99px; transition: width .4s; }
.meter-mark { position: absolute; top: -.25rem; width: 2px; height: 1.2rem; background: var(--ixd-ink); }
.big-number { font: 400 2.8rem/1 var(--ixd-serif); margin: .3rem 0; }
.chip-quiz { background: #f7ead6; color: #7a5520; margin-left: .25rem; }
.steps { grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); }

/* Lab section navigation */
.lab-steps { display: flex; flex-wrap: wrap; gap: .4rem; margin: 0 0 1.2rem; position: sticky; top: 3.6rem; z-index: 5; background: rgba(246, 244, 239, .94); padding: .5rem 0; backdrop-filter: blur(6px); }
.lab-steps a { font: 500 .76rem var(--ixd-mono); text-transform: uppercase; letter-spacing: .06em; text-decoration: none; border: 1px solid var(--ixd-line); background: var(--ixd-card); border-radius: 99px; padding: .25rem .8rem; color: var(--ixd-ink); }
.lab-steps a:hover { border-color: var(--ixd-green); color: var(--ixd-green); }
.experiment { scroll-margin-top: 7rem; }

/* Go deeper */
.deeper .accordion { --bs-accordion-bg: var(--ixd-card); --bs-accordion-border-color: var(--ixd-line); --bs-accordion-active-bg: #f1f6f3; --bs-accordion-active-color: var(--ixd-green-dark); --bs-accordion-btn-focus-box-shadow: 0 0 0 3px rgba(212, 161, 94, .45); }
.deeper .accordion-button { font-family: var(--ixd-serif); font-size: 1.08rem; }
.deeper .accordion-body p { max-width: 72ch; }
.reading li { margin-bottom: .4rem; font-size: .92rem; }

/* Quiz */
.quiz-q { border-bottom: 1px dashed var(--ixd-line); padding: .6rem 0 .2rem; margin-bottom: .6rem; }
.quiz-q .control-label { font-weight: 500; }
.quiz-fb { font-size: .9rem; border-radius: .5rem; padding: .5rem .8rem; margin: -.2rem 0 .6rem; }
.quiz-fb.right { background: #e5efe9; color: var(--ixd-green-dark); }
.quiz-fb.wrong { background: #f7ead6; color: #6b4a1b; }
.quiz-fb.todo-fb { background: var(--ixd-wire); color: var(--ixd-muted); }

/* AI tutor chat */
.tutor { border-top: 1px solid var(--ixd-line); padding-top: 1.2rem; }
.chat { display: flex; flex-direction: column; gap: .6rem; margin-bottom: .8rem; }
.chat-msg { border-radius: .8rem; padding: .7rem 1rem; max-width: 92%; }
.chat-user { align-self: flex-end; background: var(--ixd-green); color: #fff; }
.chat-ai { align-self: flex-start; background: #f1f6f3; border-left: 3px solid var(--ixd-green); }
.chat-ai ul { padding-left: 1.2rem; }

/* AI settings */
.provider-picker { display: grid; grid-template-columns: repeat(3, 1fr); gap: .6rem; border: 0; padding: 0; margin: 0 0 .8rem; }
.provider-option { display: flex; flex-direction: column; align-items: flex-start; gap: .1rem; border: 1px solid var(--ixd-line); border-radius: .7rem; padding: .7rem .9rem; cursor: pointer; position: relative; }
.provider-option input { position: absolute; opacity: 0; }
.provider-option:has(input:checked) { border-color: var(--ixd-green); box-shadow: 0 0 0 2px var(--ixd-green) inset; background: #f1f6f3; }
.provider-option:has(input:focus-visible) { outline: 3px solid var(--ixd-sand); outline-offset: 2px; }
.provider-name { font-weight: 600; }
.provider-maker { font-size: .8rem; color: var(--ixd-muted); }
.visually-hidden { position: absolute !important; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }

/* Personas */
.snippet-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(230px, 1fr)); gap: .7rem; margin: .8rem 0 1rem; }
.snippet { background: #fffbe8; border: 1px solid #ece3bd; border-radius: .5rem; padding: .7rem .8rem .2rem; font-size: .92rem; box-shadow: 0 2px 4px rgba(32, 37, 34, .05); }
.persona-card { background: var(--ixd-card); border: 1px solid var(--ixd-line); border-radius: 1rem; padding: 1.4rem; position: relative; }
.persona-avatar { width: 3.2rem; height: 3.2rem; border-radius: 50%; background: var(--ixd-green); color: #fff; display: grid; place-items: center; font: 400 1.5rem var(--ixd-serif); margin-bottom: .6rem; }
.persona-quote { font: italic 1.05rem/1.4 var(--ixd-serif); border-left: 3px solid var(--ixd-sand); padding-left: .8rem; margin: .8rem 0; color: var(--ixd-ink); }

/* Journey map */
.journey-grid { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: .7rem; margin-bottom: 1rem; }
.journey-stage { background: var(--ixd-paper); border: 1px solid var(--ixd-line); border-radius: .7rem; padding: .8rem; }
.journey-stage .form-group { margin-bottom: .5rem; }
@media (max-width: 992px) { .journey-grid { grid-template-columns: 1fr 1fr; } }
@media (max-width: 576px) { .journey-grid { grid-template-columns: 1fr; } }

/* Laws of UX experiments */
.exp-area { background: var(--ixd-paper); border: 1px solid var(--ixd-line); border-radius: .8rem; padding: .8rem; }
.exp-stage { position: relative; height: 340px; background: #fff; border: 1px dashed #c9c6bd; border-radius: .6rem; overflow: hidden; user-select: none; }
.exp-done { position: absolute; inset: 0; display: grid; place-items: center; text-align: center; padding: 1rem; color: var(--ixd-muted); margin: 0; }
