.fitts-target:hover { background: var(--ixd-green-dark); }
.hick-goal { text-align: center; margin: .8rem 0; font-size: 1.1rem; }
.hick-grid { display: flex; flex-wrap: wrap; justify-content: center; gap: .4rem; padding: 0 1rem; }
.hick-grid .btn { min-width: 6.5rem; }
.hick-wrong { border-color: #a35b4f !important; color: #a35b4f !important; }
.model-eq { font: 500 1.05rem var(--ixd-mono); margin: .4rem 0 .6rem; }

/* SUS and glossary */
.sus-items .form-group { border-bottom: 1px dashed var(--ixd-line); padding-bottom: .4rem; margin-bottom: .6rem; }
.sticky-panel { position: sticky; top: 7rem; }
.glossary dt { font-family: var(--ixd-serif); font-size: 1.2rem; font-weight: 400; margin-top: 1.1rem; }
.glossary dd { margin: .2rem 0 0; color: var(--ixd-ink); max-width: 72ch; }
.dropdown-header { font: 500 .72rem var(--ixd-mono); letter-spacing: .08em; text-transform: uppercase; color: var(--ixd-green); }
.dropdown-menu { max-height: 80vh; overflow-y: auto; }
